from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(6,'fractions','Les fractions, du tout au nombre','2 · Fractions et nombres décimaux',
'Parts · Demi-droite · Entiers cachés · Encadrements',
['Lire, représenter et écrire des fractions, au-delà de 1.','Passer d’une fraction à l’écriture entier plus fraction.','Placer et repérer des fractions sur une demi-droite.'],
['Fractions du CM1 : sens, demi-droite, encadrements.'],[
page(1,'Des parts de toutes tailles',
bloc('definition',r'La fraction $\frac{7}{12}$ désigne 7 parts d’une unité partagée en 12 parts égales. Le dénominateur nomme le partage, le numérateur compte les parts. Au CM2, les partages vont jusqu’aux soixantièmes.'),
bloc('exemple',r'Une heure partagée en 60 minutes : chaque minute est $\frac1{60}$ d’heure, et 45 minutes représentent $\frac{45}{60}$ d’heure, soit trois quarts d’heure.'),
bloc('propriete',r'Une fraction dépasse 1 quand son numérateur dépasse son dénominateur : $\frac{19}6=3+\frac16$, car $18$ sixièmes font 3 unités. L’écriture entier plus fraction situe immédiatement le nombre.'),
bloc('savoirfaire',r'Encadrer $\frac{47}{10}$ : $\frac{40}{10}=4$ et $\frac{50}{10}=5$, donc $4<\frac{47}{10}<5$. On cherche les multiples du dénominateur voisins du numérateur.','Encadrer entre deux entiers')),
page(2,'Sur la demi-droite graduée',
bloc('propriete',r'Les fractions sont des nombres : sur une demi-droite dont l’unité est partagée en 6, le point $\frac{19}6$ se place un pas après 3. Réciproquement, un point se repère par une fraction ou par un entier plus une fraction.'),
r'@FIG:cours-droite-sixiemes@',
bloc('exemple',r'Sur une même droite graduée en douzièmes, $\frac6{12}$ tombe sur le même point que $\frac12$ : deux écritures peuvent repérer le même nombre.'),
bloc('savoirfaire',r'Pour placer $2+\frac56$ : aller à l’entier 2, puis avancer de 5 pas de un sixième. Pour lire un point : compter les unités entières, puis les pas restants.','Placer vite et bien')),
],[
E('Lire des parts',r'Quelle fraction de l’heure représentent 7 minutes ? Et 45 minutes ?',r'Une minute est $\frac1{60}$ d’heure : 7 minutes font $\res{\frac7{60}}$ d’heure et 45 minutes $\res{\frac{45}{60}}$, soit trois quarts d’heure.','Prendre le soixantième comme part.','assert Rational(45,60)==Rational(3,4)'),
E('Représenter',r'La bande est partagée en 12 parts égales. Colorier $\frac5{12}$ de la bande.',r'On colorie $\res5$ parts sur les 12 ; la solution figure en vert. Tout choix de cinq parts convient.','Compter les parts du partage.','assert Rational(5,12)<1',figure='frac-2'),
E('Entier caché',r'Écrire $\frac{19}6$ et $\frac{48}8$ plus simplement, avec un entier et, si besoin, une fraction.',r'$18$ sixièmes font 3 unités : $\frac{19}6=\res{3+\frac16}$. Et $\frac{48}8=\res6$ exactement.','Chercher les paquets complets du dénominateur.','assert Rational(19,6)==3+Rational(1,6) and Rational(48,8)==6'),
E('Recomposer',r'Écrire $4+\frac3{10}$ puis $2+\frac56$ sous la forme d’une seule fraction.',r'$4=\frac{40}{10}$ donc $4+\frac3{10}=\res{\frac{43}{10}}$. De même $2=\frac{12}6$ et $2+\frac56=\res{\frac{17}6}$.','Convertir les entiers dans la part utilisée.','assert 4+Rational(3,10)==Rational(43,10) and 2+Rational(5,6)==Rational(17,6)'),
E('Encadrer',r'Encadrer entre deux entiers consécutifs : $\frac{47}{10}$, puis $\frac{23}4$.',r'$\res{4<\frac{47}{10}<5}$, car $40<47<50$. Et $\res{5<\frac{23}4<6}$, car $20<23<24$.','Encadrer le numérateur par des multiples du dénominateur.','assert 4<Rational(47,10)<5 and 5<Rational(23,4)<6'),
E('Lire la demi-droite',r'L’unité est partagée en sixièmes. Lire les nombres repérés par A et B, de deux façons chacun.',r'A est 2 pas après 1 : $\res{1+\frac26=\frac86}$. B est 1 pas après 3 : $\res{3+\frac16=\frac{19}6}$.','Compter les unités puis les pas.','assert 1+Rational(2,6)==Rational(8,6) and 3+Rational(1,6)==Rational(19,6)',figure='fd-6'),
E('Placer des fractions',r'Sur la demi-droite graduée en cinquièmes, placer $C\left(\frac85\right)$ et $D\left(2+\frac35\right)$.',r'C se place 3 pas après 1, D trois pas après 2. Les positions figurent en vert au corrigé.','Convertir en entier plus fraction avant de placer.','assert Rational(8,5)==1+Rational(3,5) and 2+Rational(3,5)==Rational(13,5)',figure='fd-7'),
E('Le même point',r'Sur une droite graduée en douzièmes, les fractions $\frac6{12}$ et $\frac12$ repèrent-elles le même point ? Justifier avec les pas.',r'$\res{\text{Oui}}$ : 6 pas de un douzième couvrent la moitié de l’unité, exactement comme $\frac12$. Deux écritures différentes peuvent désigner le même nombre.','Compter les pas couverts par chaque écriture.','assert Rational(6,12)==Rational(1,2)',figure='fd-8'),
E('Un entier tout rond',r'Compléter : $\frac{\square}{15}=2$ ; $\frac{36}{\square}=4$ ; $\frac{\square}{60}=1$.',r'$2=\frac{30}{15}$ : $\square=\res{30}$. $36:9=4$ : $\square=\res9$. Une unité entière : $\square=\res{60}$.','Multiplier l’entier par le dénominateur.','assert Rational(30,15)==2 and Rational(36,9)==4 and Rational(60,60)==1'),
E('Les tours de piste',r'Un coureur a parcouru $\frac{11}4$ de tour de piste. Combien de tours complets a-t-il bouclés ? Quelle fraction de tour lui reste-t-elle pour finir le troisième tour ?',r'$\frac{11}4=2+\frac34$ : $\res2$ tours complets et trois quarts du troisième. Il lui reste $\res{\frac14}$ de tour pour finir le troisième.','Extraire les tours entiers.','assert Rational(11,4)==2+Rational(3,4) and 3-Rational(11,4)==Rational(1,4)'),
E('Les gobelets',r'Avec un pichet de $\frac{13}4$ de litre, combien de gobelets d’un quart de litre peut-on remplir ? Que reste-t-il après avoir rempli 3 gobelets ?',r'Treize quarts remplissent $\res{13}$ gobelets d’un quart. Après 3 gobelets, il reste $\frac{13}4-\frac34=\frac{10}4$ de litre, soit $\res{2+\frac24}$ litres.','Compter directement les quarts.','assert Rational(13,4)-Rational(3,4)==Rational(10,4) and Rational(10,4)==2+Rational(2,4)'),
E('Entre deux entiers',r'Trouver trois fractions de dénominateur 6 strictement comprises entre 2 et 3.',r'Entre $\frac{12}6$ et $\frac{18}6$, on peut choisir $\res{\frac{13}6,\ \frac{14}6,\ \frac{17}6}$ par exemple : tout numérateur de 13 à 17 convient.','Convertir les bornes en sixièmes.','assert 2<Rational(13,6)<Rational(14,6)<Rational(17,6)<3'),
E('Le pot de peinture',r'Un peintre a utilisé $\frac{35}{10}$ de pot de peinture pour un chantier. Écrire cette quantité avec un entier, puis dire combien de pots entamés il a ouverts au minimum.',r'$\frac{35}{10}=\res{3+\frac5{10}}$ : trois pots entiers et la moitié d’un quatrième. Il a ouvert au minimum $\res4$ pots.','Lire l’entier puis interpréter le reste.','assert Rational(35,10)==3+Rational(5,10) and 3+1==4'),
E('Comparer à l’unité et à 2',r'Classer ces fractions en trois groupes — plus petites que 1, entre 1 et 2, plus grandes que 2 : $\frac79$ ; $\frac{13}9$ ; $\frac{25}9$ ; $\frac99$.',r'$\frac79<1$ ; $\frac99=1$ ; $\frac{13}9$ est entre 1 et 2, car $9<13<18$ ; $\frac{25}9>2$, car $25>18$. Groupes : $\res{\frac79}$ ; $\res{\frac{13}9}$ ; $\res{\frac{25}9}$ ; et $\frac99$ vaut exactement 1.','Comparer le numérateur à 9 et à 18.','assert Rational(7,9)<1 and 1<Rational(13,9)<2 and Rational(25,9)>2 and Rational(9,9)==1'),
E('Vrai ou faux ?',r'Issa affirme : « $\frac{60}{59}$ et $\frac{59}{60}$ sont égales, elles utilisent les mêmes nombres. » Corriger et situer chaque fraction par rapport à 1.',r'Les rôles diffèrent : $\frac{60}{59}$ dépasse 1 (60 parts d’un partage en 59), tandis que $\frac{59}{60}<1$ (il manque un soixantième). Elles sont $\res{\text{différentes}}$ : l’ordre des nombres compte.','Comparer chaque fraction à l’unité.','assert Rational(60,59)>1>Rational(59,60)')
],reperes=['Parts et dénominateurs jusqu’à 60','Entier plus fraction','Demi-droite et repérages','Encadrements et problèmes'],deco='calcul')

chapitre(7,'comparer-fractions','Comparer et additionner des fractions','2 · Fractions et nombres décimaux',
'Mêmes parts · Parts compatibles · Sommes',
['Comparer des fractions de même dénominateur ou de même numérateur.','Rendre deux fractions compatibles quand un dénominateur est multiple de l’autre.','Additionner et soustraire des fractions compatibles.'],
['Multiples, diviseurs et fractions sur la demi-droite.'],[
page(1,'Comparer des fractions',
bloc('propriete',r'Même dénominateur : la plus grande a le plus grand numérateur, $\frac79>\frac59$. Même numérateur : la plus grande a le plus petit dénominateur, $\frac35>\frac38$, car les cinquièmes sont plus grands que les huitièmes.'),
bloc('savoirfaire',r'Quand un dénominateur est un multiple de l’autre, convertir : $\frac56$ et $\frac{11}{12}$ se comparent en douzièmes, car $6\times2=12$ : $\frac56=\frac{10}{12}<\frac{11}{12}$.','Changer d’écriture pour comparer'),
bloc('exemple',r'Comparer à 1 aide souvent : $\frac98>1>\frac78$. Et comparer à $\frac12$ : $\frac38<\frac12$ car $\frac12=\frac48$ ; $\frac7{12}>\frac12$ car $\frac12=\frac6{12}$.'),
bloc('attention',r'$\frac56=\frac{10}{12}$ : multiplier le numérateur et le dénominateur par le même nombre ne change pas le nombre, car les parts deviennent deux fois plus fines mais deux fois plus nombreuses.')),
page(2,'Additionner et soustraire',
bloc('propriete',r'Avec le même dénominateur, les parts s’ajoutent : $\frac5{12}+\frac4{12}=\frac9{12}$ et $\frac{11}{12}-\frac7{12}=\frac4{12}$.'),
bloc('savoirfaire',r'Quand un dénominateur est multiple de l’autre, convertir d’abord : $\frac34+\frac58=\frac68+\frac58=\frac{11}8$, soit $1+\frac38$. Les huitièmes conviennent, car $8$ est un multiple de $4$.','Convertir puis réunir'),
bloc('exemple',r'Compléter à l’unité : $\frac7{10}+\frac3{10}=1$. Retirer à une unité : $1-\frac4{15}=\frac{15}{15}-\frac4{15}=\frac{11}{15}$. Retirer à un entier : $2-\frac56=\frac{12}6-\frac56=\frac76$.'),
bloc('attention',r'On n’additionne jamais les dénominateurs : $\frac14+\frac14$ fait $\frac24$, deux quarts, et sûrement pas $\frac28$. Le partage ne change pas quand on réunit des parts.'))
],[
E('Mêmes parts',r'Comparer $\frac79$ et $\frac59$, puis ranger par ordre croissant : $\frac8{15}$ ; $\frac2{15}$ ; $\frac{11}{15}$.',r'$\res{\frac79>\frac59}$ : mêmes parts, plus de parts. Ordre : $\res{\frac2{15}<\frac8{15}<\frac{11}{15}}$.','À parts égales, comparer les numérateurs.','assert Rational(7,9)>Rational(5,9) and Rational(2,15)<Rational(8,15)<Rational(11,15)'),
E('Mêmes numérateurs',r'Comparer $\frac35$ et $\frac38$, puis $\frac7{10}$ et $\frac7{12}$.',r'Trois parts chacune, mais les cinquièmes sont plus grands : $\res{\frac35>\frac38}$. De même $\res{\frac7{10}>\frac7{12}}$.','À numérateur égal, le plus petit dénominateur l’emporte.','assert Rational(3,5)>Rational(3,8) and Rational(7,10)>Rational(7,12)'),
E('Écritures équivalentes',r'Compléter : $\frac56=\frac{\square}{12}$ ; $\frac34=\frac{\square}{20}$ ; $\frac{2}{3}=\frac{\square}{60}$.',r'Les parts deviennent plus fines : $\frac56=\res{\frac{10}{12}}$ ; $\frac34=\res{\frac{15}{20}}$ ; $\frac23=\res{\frac{40}{60}}$.','Multiplier haut et bas par le même nombre.','assert Rational(5,6)==Rational(10,12) and Rational(3,4)==Rational(15,20) and Rational(2,3)==Rational(40,60)'),
E('Comparer en convertissant',r'Comparer $\frac56$ et $\frac{11}{12}$, puis $\frac23$ et $\frac7{12}$.',r'$\frac56=\frac{10}{12}<\frac{11}{12}$ : $\res{\frac56<\frac{11}{12}}$. $\frac23=\frac8{12}>\frac7{12}$ : $\res{\frac23>\frac7{12}}$.','Convertir vers le dénominateur multiple.','assert Rational(5,6)<Rational(11,12) and Rational(2,3)>Rational(7,12)'),
E('Autour de un demi',r'Comparer chaque fraction à $\frac12$ : $\frac38$ ; $\frac7{12}$ ; $\frac5{10}$.',r'$\frac12=\frac48$ : $\res{\frac38<\frac12}$. $\frac12=\frac6{12}$ : $\res{\frac7{12}>\frac12}$. $\frac5{10}=\res{\frac12}$ exactement.','Écrire un demi avec le dénominateur utile.','assert Rational(3,8)<Rational(1,2) and Rational(7,12)>Rational(1,2) and Rational(5,10)==Rational(1,2)'),
E('Sommes directes',r'Calculer $\frac5{12}+\frac4{12}$, puis $\frac{11}{15}-\frac4{15}$.',r'$\res{\frac9{12}}$ et $\res{\frac7{15}}$ : les parts s’ajoutent ou se retirent, le partage reste.','Garder le dénominateur commun.','assert Rational(5,12)+Rational(4,12)==Rational(9,12) and Rational(11,15)-Rational(4,15)==Rational(7,15)'),
E('Convertir puis additionner',r'Calculer $\frac34+\frac58$, puis $\frac23+\frac16$.',r'$\frac34=\frac68$ : $\frac68+\frac58=\res{\frac{11}8}=1+\frac38$. $\frac23=\frac46$ : $\frac46+\frac16=\res{\frac56}$.','Convertir vers le dénominateur multiple.','assert Rational(3,4)+Rational(5,8)==Rational(11,8) and Rational(2,3)+Rational(1,6)==Rational(5,6)'),
E('Retirer à un entier',r'Calculer $1-\frac4{15}$, puis $2-\frac56$.',r'$1=\frac{15}{15}$ : il reste $\res{\frac{11}{15}}$. $2=\frac{12}6$ : il reste $\frac{12}6-\frac56=\res{\frac76}$, soit $1+\frac16$.','Écrire l’entier avec le dénominateur utile.','assert 1-Rational(4,15)==Rational(11,15) and 2-Rational(5,6)==Rational(7,6)'),
E('Compléter',r'Compléter : $\frac7{10}+\square=1$ ; $\frac38+\square=\frac78$ ; $\square-\frac5{12}=\frac1{12}$.',r'$\square=\res{\frac3{10}}$ ; $\square=\res{\frac48}$ ; $\square=\frac1{12}+\frac5{12}=\res{\frac6{12}}$, soit un demi.','Penser « ce qui manque » ou « défaire ».','assert Rational(7,10)+Rational(3,10)==1 and Rational(3,8)+Rational(4,8)==Rational(7,8) and Rational(6,12)-Rational(5,12)==Rational(1,12)'),
E('L’erreur classique',r'Mehdi écrit : $\frac14+\frac14=\frac28$. Expliquer son erreur avec une image de parts, puis corriger.',r'Réunir deux quarts donne deux parts d’un partage en 4, pas un partage en 8 : $\frac14+\frac14=\res{\frac24}$, la moitié. On n’additionne jamais les dénominateurs.','Revenir aux parts d’une même unité.','assert Rational(1,4)+Rational(1,4)==Rational(2,4) and Rational(2,4)!=Rational(2,8)'),
E('La tarte partagée',r'Léa mange $\frac38$ d’une tarte, Max en mange $\frac14$.'+Q(r'Quelle fraction de la tarte ont-ils mangée ensemble ?',r'Quelle fraction reste-t-il ?'),r'$\frac14=\frac28$ : ensemble $\frac38+\frac28=\res{\frac58}$. Il reste $1-\frac58=\res{\frac38}$ de tarte. Contrôle : $\frac58+\frac38=1$.','Convertir les quarts en huitièmes.','assert Rational(3,8)+Rational(1,4)==Rational(5,8) and 1-Rational(5,8)==Rational(3,8)'),
E('Le trajet en trois temps',r'Un trajet est fait aux $\frac7{12}$ en bus, à $\frac14$ en tram, et le reste à pied. Quelle fraction du trajet est faite à pied ?',r'$\frac14=\frac3{12}$ : bus et tram couvrent $\frac7{12}+\frac3{12}=\frac{10}{12}$. À pied : $1-\frac{10}{12}=\res{\frac2{12}}$, soit un sixième du trajet.','Réunir les parts connues avant le reste.','assert Rational(7,12)+Rational(1,4)==Rational(10,12) and 1-Rational(10,12)==Rational(2,12)'),
E('Les bouteilles d’eau',r'Un sportif boit $\frac34$ de litre le matin et $\frac58$ de litre l’après-midi. A-t-il bu plus ou moins d’un litre ? De combien ?',r'$\frac34=\frac68$ : total $\frac68+\frac58=\frac{11}8=1+\frac38$. Il a bu $\res{\text{plus}}$ d’un litre, de $\res{\frac38}$ de litre.','Comparer la somme à l’unité.','assert Rational(3,4)+Rational(5,8)==Rational(11,8) and Rational(11,8)-1==Rational(3,8)'),
E('Le classement des lectures',r'Trois élèves ont lu le même livre. Ana en est aux $\frac7{10}$, Bilal aux $\frac35$, Chloé aux $\frac34$. Qui est le plus avancé ? Ranger les trois avancées.',r'En vingtièmes : $\frac7{10}=\frac{14}{20}$, $\frac35=\frac{12}{20}$, $\frac34=\frac{15}{20}$. Ordre croissant : $\res{\frac35<\frac7{10}<\frac34}$ : c’est $\res{\text{Chloé}}$ la plus avancée.','Choisir un dénominateur commun aux trois.','assert Rational(3,5)<Rational(7,10)<Rational(3,4)'),
E('Un pas vers l’abstrait',r'Sans convertir, expliquer pourquoi $\frac5{13}+\frac8{13}=1$, puis calculer $\frac{37}{60}+\frac{23}{60}$.',r'Cinq parts et huit parts font treize parts d’un partage en treize : l’unité entière, $\res{\frac5{13}+\frac8{13}=1}$. De même $37+23=60$ : $\res{\frac{37}{60}+\frac{23}{60}=1}$.','Observer quand les numérateurs recomposent le dénominateur.','assert Rational(5,13)+Rational(8,13)==1 and Rational(37,60)+Rational(23,60)==1')
],reperes=['Comparaisons directes','Écritures équivalentes','Sommes et différences compatibles','Problèmes de parts'],deco='calcul')

chapitre(8,'fraction-quantite','Prendre une fraction d’une quantité','2 · Fractions et nombres décimaux',
'Opérateur · Deux tiers de… · Problèmes',
['Calculer une fraction d’une quantité ou d’une grandeur.','Multiplier un entier par une fraction.','Retrouver le tout à partir d’une part dans des cas simples.'],
['Fractions et division euclidienne.'],[
page(1,'Une fraction qui agit',
bloc('definition',r'Prendre $\frac23$ de 12, c’est partager 12 en 3 parts égales, puis prendre 2 parts : $12:3=4$, puis $4\times2=8$. On note aussi ce calcul $\frac23\times12=8$.'),
bloc('exemple',r'Trois quarts de 100 mètres : $100:4=25$, puis $25\times3=75$ mètres. Deux tiers de 12 euros : $12:3=4$, puis $4\times2=8$ euros.'),
bloc('propriete',r'Le produit d’un entier par une fraction peut se calculer dans l’ordre le plus simple : $\frac34\times60$ se calcule $60:4=15$ puis $15\times3=45$ ; ou $3\times60=180$ puis $180:4=45$ : même résultat.'),
bloc('savoirfaire',r'Contrôler l’ordre de grandeur : $\frac23$ de 12 doit être plus petit que 12 (fraction inférieure à 1) et plus grand que la moitié de 12, car $\frac23>\frac12$.','Encadrer le résultat attendu')),
page(2,'Du tout à la part, et retour',
bloc('savoirfaire',r'Retrouver le tout : si $\frac13$ d’une somme vaut 15 euros, le tout vaut $15\times3=45$ euros. Si $\frac25$ d’un trajet font 30 km, un cinquième fait $30:2=15$ km, et le trajet entier $15\times5=75$ km.','Remonter à l’unité de part'),
bloc('exemple',r'Une classe de 28 élèves : les $\frac47$ sont des filles, soit $28:7=4$, puis $4\times4=16$ filles ; il y a donc $28-16=12$ garçons. Le contrôle $16+12=28$ rassure.'),
bloc('attention',r'La fraction agit sur le tout annoncé, pas sur un reste : « $\frac14$ de 60, puis $\frac13$ du reste » fait $15$, puis $\frac13$ de 45, soit 15 encore. Lire à chaque étape sur quoi porte la fraction.'),
bloc('propriete',r'Prendre $\frac55$ d’une quantité la laisse entière ; prendre $\frac{10}5$, c’est la doubler : une fraction plus grande que 1 agrandit.'))
],[
E('Des parts simples',r'Calculer $\frac13$ de 18, puis $\frac14$ de 32.',r'$18:3=\res6$ et $32:4=\res8$.','Partager selon le dénominateur.','assert 18//3==6 and 32//4==8'),
E('Deux tiers de douze',r'Calculer $\frac23$ de 12 euros, puis $\frac34$ de 100 mètres.',r'$12:3=4$ puis $4\times2=\res8$ euros. $100:4=25$ puis $25\times3=\res{75}$ mètres.','Partager puis multiplier.','assert 12//3*2==8 and 100//4*3==75'),
E('Deux chemins, un produit',r'Calculer $\frac34\times60$ de deux façons : en partageant d’abord, puis en multipliant d’abord.',r'$60:4=15$ puis $15\times3=\res{45}$. Ou $3\times60=180$ puis $180:4=\res{45}$ : les deux chemins mènent au même produit.','Choisir l’ordre qui donne des calculs ronds.','assert 60//4*3==45 and 3*60//4==45 and Rational(3,4)*60==45'),
E('Encadrer avant de calculer',r'Sans calculer exactement, dire entre quels nombres se trouve $\frac23$ de 12, puis vérifier par le calcul.',r'$\frac23<1$ : le résultat est plus petit que 12 ; $\frac23>\frac12$ : plus grand que 6. Calcul : $\res8$, bien entre 6 et 12.','Comparer la fraction à 1 et à un demi.','assert 6<Rational(2,3)*12<12 and Rational(2,3)*12==8'),
E('Des fractions d’heure',r'Convertir en minutes : $\frac14$ d’heure ; $\frac34$ d’heure ; $\frac1{6}$ d’heure.',r'$60:4=\res{15}$ min ; $15\times3=\res{45}$ min ; $60:6=\res{10}$ min.','Prendre la fraction de 60 minutes.','assert 60//4==15 and 60//4*3==45 and 60//6==10'),
E('La jauge du réservoir',r'Un réservoir de 48 litres est rempli aux $\frac38$.'+Q(r'Quel volume d’essence contient-il ?',r'Quel volume manque-t-il pour le remplir ?'),r'$48:8=6$ puis $6\times3=\res{18}$ litres. Il manque $48-18=\res{30}$ litres, soit les $\frac58$ du réservoir.','Calculer la part puis le complément.','assert 48//8*3==18 and 48-18==30 and Rational(5,8)*48==30'),
E('Retrouver le tout',r'Le tiers d’une somme vaut 15 euros. Quelle est la somme ? Les $\frac25$ d’un trajet font 30 km. Quelle est la longueur du trajet ?',r'Le tout vaut $15\times3=\res{45}$ euros. Un cinquième fait $30:2=15$ km, le trajet $15\times5=\res{75}$ km.','Revenir d’abord à une seule part.','assert 15*3==45 and 30//2*5==75'),
E('La classe de 28',r'Dans une classe de 28 élèves, les $\frac47$ sont des filles. Combien y a-t-il de filles ? De garçons ?',r'$28:7=4$, puis $4\times4=\res{16}$ filles, et $28-16=\res{12}$ garçons. Contrôle : $16+12=28$.','Partager en 7 puis compter 4 parts.','assert 28//7*4==16 and 28-16==12'),
E('Plus grand que le tout ?',r'Calculer $\frac55$ de 35, puis $\frac{10}5$ de 35. Que remarque-t-on ?',r'$\frac55$ de 35 vaut $\res{35}$ : la quantité entière. $\frac{10}5$ de 35 vaut $35\times2=\res{70}$ : une fraction plus grande que 1 $\res{\text{agrandit}}$.','Comparer la fraction à l’unité.','assert Rational(5,5)*35==35 and Rational(10,5)*35==70'),
E('L’étape de la fraction',r'Sur 60 euros, Tom dépense $\frac14$ le matin, puis $\frac13$ du reste l’après-midi. Combien dépense-t-il chaque fois, et que lui reste-t-il ?',r'Matin : $60:4=\res{15}$ euros ; reste 45. Après-midi : $\frac13$ de 45, soit $\res{15}$ euros ; reste $45-15=\res{30}$ euros. La seconde fraction agit sur le reste, pas sur 60.','Repérer le tout de chaque fraction.','assert 60//4==15 and 60-15==45 and 45//3==15 and 45-15==30'),
E('Le jardin potager',r'Un jardin de 120 m² consacre $\frac25$ de sa surface aux légumes et $\frac3{10}$ aux fleurs. Quelle surface occupe chaque partie ? Quelle surface reste-t-il en pelouse ?',r'Légumes : $120:5=24$, puis $24\times2=\res{48}$ m². Fleurs : $120:10=12$, puis $12\times3=\res{36}$ m². Pelouse : $120-48-36=\res{36}$ m².','Traiter chaque fraction du même tout.','assert 120//5*2==48 and 120//10*3==36 and 120-48-36==36'),
E('Le prix soldé',r'Un blouson coûte 60 euros. Pendant les soldes, il est vendu aux $\frac34$ de son prix. Quel est le nouveau prix ? Quelle économie cela fait-il ?',r'Nouveau prix : $60:4\times3=\res{45}$ euros. Économie : $60-45=\res{15}$ euros, soit le quart du prix.','Calculer la part conservée puis l’écart.','assert 60//4*3==45 and 60-45==15'),
E('La collecte',r'Une école veut collecter 600 livres. Elle en a déjà reçu les $\frac56$. Combien de livres manquent-ils ?',r'Reçus : $600:6\times5=500$ livres. Il manque $600-500=\res{100}$ livres, soit $\frac16$ de l’objectif.','Passer par la part déjà remplie.','assert 600//6*5==500 and 600-500==100'),
E('Qui a raison ?',r'Pour calculer $\frac23$ de 18, Aya calcule $18:3\times2$ et Noé calcule $18\times2:3$. Qui a raison ? Justifier en effectuant les deux calculs.',r'Aya : $6\times2=\res{12}$. Noé : $36:3=\res{12}$. $\res{\text{Les deux ont raison}}$ : partager puis multiplier, ou multiplier puis partager, mènent au même résultat.','Effectuer les deux chemins jusqu’au bout.','assert 18//3*2==12 and 18*2//3==12'),
E('Le tout mystère',r'Après avoir dépensé les $\frac34$ de ses économies, Jade possède encore 12 euros. Quel était le montant de ses économies ?',r'Il lui reste $\frac14$ des économies : un quart vaut 12 euros, donc le tout valait $12\times4=\res{48}$ euros. Contrôle : $\frac34$ de 48 font 36, et $48-36=12$.','Travailler sur la fraction restante.','assert 12*4==48 and 48-48//4*3==12')
],reperes=['Fraction d’une quantité','Produit entier par fraction','Retrouver le tout','Problèmes à étapes'],deco='calcul')
